#!/usr/bin/env python3
"""Generate the C byte-array header used to embed YLang's generated-C runtime.

Usage:
  python3 tools/embed_text.py runtime/runtime_template.c build/runtime_template.h
  python3 tools/embed_text.py runtime/runtime_template.c build/runtime_template.h --check
"""
from __future__ import annotations

import argparse
from pathlib import Path
import sys


def render(data: bytes) -> bytes:
    lines = [
        "#ifndef YLANG_RUNTIME_TEMPLATE_H",
        "#define YLANG_RUNTIME_TEMPLATE_H",
        "",
        "/* Generated by tools/embed_text.py from runtime/runtime_template.c. */",
        "static const unsigned char ylang_runtime_template[] = {",
    ]
    for offset in range(0, len(data), 16):
        chunk = data[offset:offset + 16]
        lines.append("    " + ", ".join(f"0x{byte:02x}" for byte in chunk) + ",")
    lines.extend(["};", "", "#endif", ""])
    return "\n".join(lines).encode("ascii")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--check", action="store_true",
                        help="fail instead of writing if the output is stale")
    args = parser.parse_args()
    try:
        expected = render(args.source.read_bytes())
        if args.check:
            if not args.output.exists() or args.output.read_bytes() != expected:
                print(f"generated runtime header is stale: {args.output}", file=sys.stderr)
                print(f"regenerate with: python3 {Path(__file__)} {args.source} {args.output}",
                      file=sys.stderr)
                return 1
            return 0
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_bytes(expected)
    except OSError as exc:
        print(f"embed_text.py: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
